-- Phase 4F: Greece-aware MDRO and carbapenem-resistant organism knowledge.
insert into public.lira_knowledge_sources(organization_id,source_type,title,authority,source_url,source_version,language,status,metadata,ingestion_status)
values
(null,'guideline','Οδηγίες για τη διάγνωση, την πρόληψη και τον έλεγχο της διασποράς στελεχών Candida auris στο νοσοκομειακό περιβάλλον','ΕΟΔΥ','https://eody.gov.gr/wp-content/uploads/2024/03/Candida-auris-2023.pdf','2023','el','review',jsonb_build_object('official',true,'topic','candida-auris-greece','jurisdiction','Greece','review_required',true,'phase','4F'),'pending'),
(null,'guideline','Guidelines for prevention and control of CRE, CRAB and CRPsA in health care facilities','WHO','https://www.who.int/publications/i/item/9789241550178','2017','en','review',jsonb_build_object('official',true,'topic','carbapenem-resistant-organisms','review_required',true,'phase','4F','dated_guidance',true),'pending'),
